#include <vector>

class Solution {
public:
    int calculateLateFee(std::vector<int>& returnDate, std::vector<int>& dueDate) {
        int rd = returnDate[0], rm = returnDate[1], ry = returnDate[2];
        int dd = dueDate[0], dm = dueDate[1], dy = dueDate[2];

        if (ry < dy) return 0;
        if (ry > dy) return 10000;
        if (rm < dm) return 0;
        if (rm > dm) return 500 * (rm - dm);
        if (rd <= dd) return 0;
        return 15 * (rd - dd);
    }
};

class Solution {
    public int calculateLateFee(int[] returnDate, int[] dueDate) {
        int rd = returnDate[0], rm = returnDate[1], ry = returnDate[2];
        int dd = dueDate[0], dm = dueDate[1], dy = dueDate[2];

        if (ry < dy) return 0;
        if (ry > dy) return 10000;
        if (rm < dm) return 0;
        if (rm > dm) return 500 * (rm - dm);
        if (rd <= dd) return 0;
        return 15 * (rd - dd);
    }
}

var calculateLateFee = function(returnDate, dueDate) {
    const [rd, rm, ry] = returnDate;
    const [dd, dm, dy] = dueDate;

    if (ry < dy) return 0;
    if (ry > dy) return 10000;
    if (rm < dm) return 0;
    if (rm > dm) return 500 * (rm - dm);
    if (rd <= dd) return 0;
    return 15 * (rd - dd);
};
